from typing import Callable

def iterate_orbit(step: Callable[[float], float], x0: float, steps: int) -> list[float]:
    """Compute x_0 through x_steps."""
    if steps < 0:
        raise ValueError("steps must be nonnegative")
    xs = [x0]
    for _ in range(steps):
        xs.append(step(xs[-1]))
    return xs

if __name__ == "__main__":
    logistic = lambda x: 3.83 * x * (1.0 - x)
    print(iterate_orbit(logistic, 0.5, 20))

from dataclasses import dataclass
from typing import Sequence

@dataclass(frozen=True)
class ReturnCandidate:
    index: int
    lag: int
    error: float

def near_returns(xs: Sequence[float], max_lag: int, tolerance: float) -> list[ReturnCandidate]:
    """Find finite-precision near returns; these are not exact period proofs."""
    if max_lag < 1 or tolerance < 0:
        raise ValueError("invalid lag or tolerance")
    return [ReturnCandidate(i, p, abs(xs[i] - xs[i-p]))
            for i in range(1, len(xs))
            for p in range(1, min(i, max_lag) + 1)
            if abs(xs[i] - xs[i-p]) <= tolerance]

from fractions import Fraction

def logistic_exact(x: Fraction) -> Fraction:
    return Fraction(383, 100) * x * (1 - x)

def classified_fixed_points() -> tuple[Fraction, Fraction]:
    points = (Fraction(0), Fraction(283, 383))
    assert all(logistic_exact(x) == x for x in points)
    return points

if __name__ == "__main__":
    print(classified_fixed_points())

